<template><div class="page"><h2 class="page-title">消费行为分析</h2><p class="muted">统一采用毛消费－退款＝净消费口径，转账和充值提现不进入核心消费。</p><div v-if="data.has_data" class="grid section"><div class="card" style="grid-column:span 2"><h3>周度净消费</h3><EChart :option="weekly"/></div><div class="card" style="grid-column:span 2"><h3>月度毛额、退款与净额</h3><EChart :option="monthly"/></div><div class="card" style="grid-column:span 2"><h3>类别金额占比</h3><EChart :option="category"/></div><div class="card" style="grid-column:span 2"><h3>工作日与周末日均</h3><EChart :option="dayType"/></div><div class="card" style="grid-column:span 4"><h3>主要分类周度趋势</h3><EChart :option="categoryTrend"/></div><div class="card" style="grid-column:span 4"><h3>统计异常周</h3><p class="muted">由后端按完整周IQR规则识别；异常不等于不合理消费。</p><el-table :data="data.anomaly_weeks"><el-table-column prop="week_start" label="周开始"/><el-table-column label="净消费"><template #default="s">{{formatMoney(s.row.net_consumption_minor)}}</template></el-table-column><el-table-column prop="large_transaction_count" label="大额交易数"/><el-table-column prop="anomaly_direction" label="方向"/></el-table></div></div><EmptyGuide v-else description="暂无可分析交易，请先导入账单" action="/bills"/></div></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { api } from '../api/client.js';import EChart from '../components/EChart.vue';import EmptyGuide from '../components/EmptyGuide.vue';import { formatMoney } from '../utils/money.js'
const data=ref({});onMounted(async()=>data.value=await api.get('/analytics/overview'));const tip={trigger:'axis',valueFormatter:v=>formatMoney(v)}
const weekly=computed(()=>({tooltip:tip,xAxis:{type:'category',data:(data.value.weekly||[]).map(x=>x.week_start)},yAxis:{type:'value'},series:[{type:'line',data:(data.value.weekly||[]).map(x=>x.net_consumption_minor),color:'#2b9a72'}]}))
const monthly=computed(()=>({tooltip:tip,legend:{},xAxis:{type:'category',data:(data.value.monthly||[]).map(x=>x.year_month)},yAxis:{type:'value'},series:['gross_consumption_minor','refund_minor','net_consumption_minor'].map((k,i)=>({name:['毛消费','退款','净消费'][i],type:'bar',data:(data.value.monthly||[]).map(x=>x[k])}))}))
const category=computed(()=>({tooltip:{trigger:'item',valueFormatter:v=>formatMoney(v)},series:[{type:'pie',radius:['45%','70%'],data:(data.value.categories||[]).map(x=>({name:x.category_code,value:x.net_consumption_minor}))}]}))
const dayType=computed(()=>({tooltip:tip,xAxis:{type:'category',data:(data.value.weekday_weekend||[]).map(x=>x.is_weekend?'周末':'工作日')},yAxis:{type:'value'},series:[{type:'bar',data:(data.value.weekday_weekend||[]).map(x=>x.daily_average_minor),color:'#4d7c72'}]}))
const categoryTrend=computed(()=>{const top=(data.value.categories||[]).slice().sort((a,b)=>b.net_consumption_minor-a.net_consumption_minor).slice(0,5).map(x=>x.category_code),weeks=[...new Set((data.value.category_weekly||[]).map(x=>x.week_start))];return{tooltip:tip,legend:{},xAxis:{type:'category',data:weeks},yAxis:{type:'value'},series:top.map(code=>({name:code,type:'line',showSymbol:false,data:weeks.map(w=>(data.value.category_weekly||[]).find(x=>x.week_start===w&&x.category_code===code)?.net_consumption_minor||0)}))}})
</script>
